export const content={title:'Small things. Quiet direction.',reference:'1 NEPHI 16:28–29',summary:'As Lehi’s family traveled in the wilderness, the Liahona’s pointers worked according to their faith, diligence, and attention. Its changing instructions invited them to notice that great things can come through small means.',connection:'Alma later used the Liahona to teach his son Helaman. Just as the instrument pointed the family toward a promised land, the words of Christ can point us toward eternal life. The connection shifts our attention from the object itself to the guidance it illustrates.',prompt:'What small invitation could you pay closer attention to in your life?'};
